# First-use terminology and symbol explanations accompany the visible diagrams.
TERMS={
'network':['輸入向量：一筆資料的多個座標','輸入權重與偏置：決定單元何時反應','活化函數：把加權和轉成非線性反應','輸出權重：各個反應在總和中的係數','隱藏單元數與輸入維度：兩個不同的數量'],
'conditions':['緊緻域：此處是封閉且有界的立方體'],
'quantifiers':['容許誤差：可以接受的最大偏差','任意與存在：先給目標與精度，再選參數'],
'sup':['上確界：所有誤差的最小上界；本設定可取最大值'],
'cells':['分界點：格子左右邊界','中點：相鄰邊界的平均'],
'heights':['理想階梯：每格內固定高度的函數'],
'jumps':['跳躍幅度：下一個高度減目前高度'],
'dense':['張成：有限個單元的所有線性組合','稠密：每個目標附近都有任意精度的近似','閉包：連同可任意逼近的極限一起考慮'],
'hb':['泛函：把函數變成數的工具','連續線性：保留加法、數乘且對小變動穩定'],
'riesz':['帶符號測度：可以有正負的分布權重'],
'contradiction':['判別性：這族單元的積分足以區分測度']}
for p in PAGES:
 p['new_terms']=TERMS.get(p['kind'],[])
 if p['kind']=='network':
  p['math'].append(r'z_i=\mathbf w_i^\top\mathbf x+\theta_i')
